using System;
using System.Runtime.CompilerServices;
using System.Runtime.Intrinsics;
using System.Threading;

namespace EasyEcs;

// Component access and the structural changes that move an entity between archetype tables. The public T1..T9
// overloads are generated by EasyEcs.Generator.
public sealed partial class World
{
    /// <summary>
    /// Passes iterating this world right now (ForEach, query enumerators). While one runs, rows that lose their entity
    /// become tombstones that keep their data (the pass carries writes through its refs over to the entity's new row)
    /// instead of being filled by the last row; the last pass to end closes them (<see cref="EndPass"/>).
    /// </summary>
    internal int Passes;
    internal long _stop; // where the last structural row loop stopped (see the generated ForEach loops)

    /// <summary>
    /// The id of the entity a structural row loop just visited at <paramref name="row"/>, read back after its job: the
    /// row is its own, or the tombstone it left (the id's complement, see <see cref="Archetype.Remove"/>), since rows do
    /// not shift during a pass. The loops keep no id across the job, so the job's values keep more registers.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static int VisitedId(in EntityId row) => row.Index ^ (row.Index >> 31);

    /// <summary>
    /// Whether a lean structural row loop over rows up to <paramref name="end"/> stopped at a structural change; if so,
    /// re-counts the rows left in <see cref="_stop"/> from <paramref name="count"/>, the end of the caller's rows.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal bool Stopped(int end, int count)
    {
        long stop = _stop;
        if (stop < 0) return false;
        _stop = stop & unchecked((long)0xFFFF_FFFF_0000_0000) | (uint)(count - end + (int)stop);
        return true;
    }

    // Archetypes with tombstones, closed when the last pass ends (each registered once: Archetype.Dirty).
    private Archetype[] _dirty = new Archetype[8];
    private int _dirtyCount;

    // Row counts of the tables at the start of a structural pass (ForEach with a job that may change structure), one
    // array per nesting depth: a pass takes the array of the passes running when it starts. Structural passes run on
    // the owner thread only (their systems run alone), so nested ones get distinct depths; an interrupted pass leaves
    // Passes raised until CompactArchetypes, and later passes then use deeper arrays.
    private int[][] _passCounts = [];

    /// <summary>An array of at least <paramref name="tables"/> ints for a structural pass about to begin.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal int[] PassCounts(int tables)
    {
        int depth = Passes;
        var stack = _passCounts;
        if ((uint)depth < (uint)stack.Length && stack[depth] is { } counts && counts.Length >= tables) return counts;
        return GrowPassCounts(depth, tables);
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private int[] GrowPassCounts(int depth, int tables)
    {
        if (depth >= _passCounts.Length) Array.Resize(ref _passCounts, Math.Max(depth + 1, _passCounts.Length * 2));
        return _passCounts[depth] = new int[Math.Max(tables, 8)];
    }

    /// <summary>
    /// One bit per row of the <paramref name="count"/> (at most 64) rows from <paramref name="rows"/>: set for an alive
    /// row, clear for a tombstone (negative id: a negative row read as a <c>long</c>; 2 rows per 128-bit vector, which
    /// x64 and arm64 both accelerate). Cold: only tables a pass left tombstones in.
    /// </summary>
    [MethodImpl(MethodImplOptions.NoInlining)]
    internal static ulong AliveRows(ref EntityId rows, int count)
    {
        ref long row = ref Unsafe.As<EntityId, long>(ref rows);
        ulong tombstones = 0;
        int i = 0;
        for (; i + 2 <= count; i += 2)
            tombstones |= (ulong)Vector128.LoadUnsafe(ref row, (nuint)i).ExtractMostSignificantBits() << i;
        for (; i < count; i++) tombstones |= (ulong)Unsafe.Add(ref row, i) >> 63 << i;
        return ~tombstones & (ulong.MaxValue >> (64 - count)); // count >= 1
    }

    /// <summary>Start a pass (rows that lose their entity become tombstones until it ends).</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal void BeginPass() => Interlocked.Increment(ref Passes);

    /// <summary>End a pass; the last one to end closes the tombstones left by structural changes during passes.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal void EndPass()
    {
        if (Interlocked.Decrement(ref Passes) == 0 && _dirtyCount > 0) CloseTombstones();
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private void CloseTombstones()
    {
        using (Shared())
        {
            if (Volatile.Read(ref Passes) != 0) return; // a pass started meanwhile: it will close them
            FillDirtyTables();
        }
    }

    /// <summary>Close the tombstones of every dirty table. Inside the structural gate, outside passes.</summary>
    private void FillDirtyTables()
    {
        if (_dirtyCount == 0) return;
        for (int i = 0; i < _dirtyCount; i++)
        {
            _dirty[i].FillHoles(Meta);
            _dirty[i] = null;
        }

        _dirtyCount = 0;
        StorageVersion++;
    }

    /// <summary>Remove entity row <paramref name="slot"/> from <paramref name="archetype"/>. Inside the structural gate.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private void RemoveRow(Archetype archetype, int slot)
    {
        if (!archetype.Remove(slot, Meta, Volatile.Read(ref Passes) != 0)) return;
        if (_dirtyCount == _dirty.Length) Array.Resize(ref _dirty, _dirty.Length * 2);
        _dirty[_dirtyCount++] = archetype;
    }

    /// <summary>Ref to <typeparamref name="T"/> of entity <paramref name="id"/>, whose archetype must have it.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal ref T ColumnRef<T>(ushort bit, int id) where T : struct, IComponent => ref Row<T>(ref MetaRef(id), bit);

    /// <summary>Ref to <typeparamref name="T"/> in the row of <paramref name="meta"/>, whose archetype must have it.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static ref T Row<T>(scoped ref EntityMeta meta, ushort bit) where T : struct, IComponent =>
        ref Unsafe.Add(ref meta.Archetype.Base<T>(bit), meta.Slot);

    /// <summary>
    /// Add one component bit to entity <paramref name="id"/> (<paramref name="meta"/> is its record). When its table has
    /// the column the row only gets the component back; else the entity moves along the cached archetype edge (no
    /// mask hashing). Inside the structural gate.
    /// </summary>
    internal void AddBit(ref EntityMeta meta, int id, ushort bit)
    {
        var from = meta.Archetype;
        int column = from.ColumnIndex(bit);
        if (column >= 0)
        {
            if (!from.MarkPresent(column, meta.Slot)) return;
            StorageVersion++; // passes re-read presence bits
            if (from.HasDisabled) Undisable(from, column, meta.Slot);
        }
        else MoveTo(ref meta, id, from.GetAddEdge(bit) ?? CreateEdge(from, bit));
    }

    /// <summary>
    /// Add several component bits in at most one archetype transition. The transition is cached per (source archetype,
    /// <paramref name="signature"/>), so only the first call of a signature from an archetype builds a mask. Inside the
    /// structural gate.
    /// </summary>
    internal void AddBits(ref EntityMeta meta, int id, ReadOnlySpan<ushort> bits, int signature)
    {
        var from = meta.Archetype;
        MoveTo(ref meta, id, from.GetAddSetEdge(signature) ?? CreateSetEdge(from, bits, signature));
        var archetype = meta.Archetype;
        if (!archetype.HasAbsent) return;
        bool restored = false;
        for (int i = 0; i < bits.Length; i++)
        {
            int column = archetype.ColumnIndex(bits[i]);
            if (!archetype.MarkPresent(column, meta.Slot)) continue;
            restored = true;
            if (archetype.HasDisabled) Undisable(archetype, column, meta.Slot);
        }

        if (restored) StorageVersion++; // passes re-read presence bits
    }

    /// <summary>
    /// The component of <paramref name="column"/> came back to row <paramref name="slot"/> through Set or GetOrAdd: a
    /// <see cref="Disabled{T}"/> tag of it goes (the new value replaces the kept one). Cold: tables with such tags only.
    /// </summary>
    [MethodImpl(MethodImplOptions.NoInlining)]
    private static void Undisable(Archetype archetype, int column, int slot)
    {
        if (archetype.DisablerColumn(column) is var tag and >= 0) archetype.MarkAbsent(tag, slot);
    }

    /// <summary>
    /// Remove one component bit: the row keeps its column and only loses the component (no move). A missing component
    /// is ignored. Inside the structural gate.
    /// </summary>
    internal void RemoveBit<T>(ref EntityMeta meta) where T : struct, IComponent
    {
        var archetype = meta.Archetype;
        int slot = meta.Slot;
        ushort bit = ComponentType<T>.Bit;
        int column = archetype.ColumnIndex(bit);
        if (column < 0) return;
        if (archetype.MarkAbsent(column, slot))
        {
            // Gone with T known: a tracked component's tick column is in every table that has it (WithCompanions),
            // and the removal's tick is the world's, so it is stamped like a write (and noted as a removal).
            archetype.StampRemoved<T>(slot, _changeTick);
            if (_indexByBit != null) Unindex(bit, archetype.Slots[slot].Index);
        }
        else if (!archetype.HasDisabled || !DropDisabled(archetype, column, slot)) return;

        StorageVersion++; // passes re-read presence bits
        if (archetype.HasCleanup) Released(ref meta);
    }

    /// <summary>
    /// Remove component bits (see <see cref="RemoveBit{T}"/>): the row is found once, and passes are told once that
    /// presence bits changed. Inside the structural gate.
    /// </summary>
    internal void RemoveBits(ref EntityMeta meta, ReadOnlySpan<ushort> bits)
    {
        var archetype = meta.Archetype;
        int slot = meta.Slot;
        bool removed = false;
        for (int i = 0; i < bits.Length; i++) removed |= TakeBit(archetype, slot, bits[i]);
        if (!removed) return;
        StorageVersion++; // passes re-read presence bits
        if (archetype.HasCleanup) Released(ref meta);
    }

    /// <summary>
    /// After a removal from a table with cleanup columns: a <see cref="Destroyed"/> entity whose last cleanup component
    /// went is freed. Cold: tables with cleanup columns only.
    /// </summary>
    [MethodImpl(MethodImplOptions.NoInlining)]
    private void Released(ref EntityMeta meta)
    {
        var archetype = meta.Archetype;
        int slot = meta.Slot;
        if (archetype.ColumnIndex(DestroyedBit) is not (var tag and >= 0) || !archetype.Has(tag, slot) || archetype.HoldsCleanup(slot)) return;
        var entity = archetype.Slots[slot];
        Free(ref meta, entity.Index);
        Orphaned(entity); // children it gained while retired follow it now
        if (_targetCount != 0) FollowLinks();
    }

    /// <summary>Clear the presence bit of component <paramref name="bit"/> in row <paramref name="slot"/>; false when the row lacks it.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private bool TakeBit(Archetype archetype, int slot, ushort bit)
    {
        int column = archetype.ColumnIndex(bit);
        if (column < 0) return false;
        if (!archetype.MarkAbsent(column, slot)) return archetype.HasDisabled && DropDisabled(archetype, column, slot);
        Gone(archetype, column, slot, bit);
        return true;
    }

    /// <summary>
    /// Component <paramref name="bit"/> (in <paramref name="column"/>) left row <paramref name="slot"/> (removed or
    /// disabled): a tracked component's tick records it, so Removed&lt;T&gt; filters find the row by its clear presence
    /// bit and new tick (Changed&lt;T&gt; filters require the component and skip it); an indexed one leaves its index.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private void Gone(Archetype archetype, int column, int slot, ushort bit)
    {
        if (archetype.Tracked && archetype.Info(column).Companion is var ticks and >= 0)
            archetype.SetTick(archetype.ColumnIndex(ticks), slot, _changeTick);
        if (_indexByBit != null) Unindex(bit, archetype.Slots[slot].Index);
    }

    /// <summary>
    /// Remove of a component the row keeps disabled: its <see cref="Disabled{T}"/> tag goes, and so does the kept value.
    /// Cold: tables with such tags only.
    /// </summary>
    [MethodImpl(MethodImplOptions.NoInlining)]
    private static bool DropDisabled(Archetype archetype, int column, int slot)
    {
        if (archetype.DisablerColumn(column) is not (var tag and >= 0) || !archetype.MarkAbsent(tag, slot)) return false;
        var info = archetype.Info(column);
        if (info.Managed) info.Clear(archetype.Columns[column], slot, 1);
        return true;
    }

    /// <summary>
    /// Disable component <paramref name="bit"/> of entity <paramref name="id"/>: add its <see cref="Disabled{T}"/> tag
    /// <paramref name="tag"/> and clear its presence bit, keeping the value. A tracked component's tick records it as a
    /// removal; an indexed one leaves its index. False when the entity lacks the component. Inside the structural gate.
    /// </summary>
    internal bool DisableBit(ref EntityMeta meta, int id, ushort bit, ushort tag)
    {
        var archetype = meta.Archetype;
        int column = archetype.ColumnIndex(bit);
        if (column < 0 || !archetype.Has(column, meta.Slot)) return false;
        AddBit(ref meta, id, tag); // may move the row: the value and its presence come along
        archetype = meta.Archetype;
        int slot = meta.Slot;
        column = archetype.ColumnIndex(bit);
        archetype.MarkAbsent(column, slot, keep: true);
        Gone(archetype, column, slot, bit);
        StorageVersion++; // passes re-read presence bits
        return true;
    }

    /// <summary>
    /// Enable component <paramref name="bit"/> disabled by tag <paramref name="tag"/>: the row gets the kept value back.
    /// The caller stamps and indexes it. False when the component is not disabled. Inside the structural gate.
    /// </summary>
    internal bool EnableBit(ref EntityMeta meta, ushort bit, ushort tag)
    {
        var archetype = meta.Archetype;
        int tagColumn = archetype.ColumnIndex(tag);
        if (tagColumn < 0 || !archetype.MarkAbsent(tagColumn, meta.Slot)) return false;
        archetype.MarkPresent(archetype.ColumnIndex(bit), meta.Slot);
        StorageVersion++; // passes re-read presence bits
        return true;
    }

    /// <summary>
    /// <c>Set</c> of one component on entity <paramref name="id"/> (<paramref name="meta"/> is its record): its bit added
    /// (a move when the table lacks the column), the value written, stamped and indexed. Inside the structural gate.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal void SetRow<T>(ref EntityMeta meta, int id, int version, in T value) where T : struct, IComponent
    {
        ushort bit = ComponentType<T>.Bit;
        AddBit(ref meta, id, bit);
        Row<T>(ref meta, bit) = value;
        meta.Archetype.Stamp<T>(meta.Slot, ChangeTick);
        Written(id, version, in value);
    }

    /// <summary>
    /// <c>Enable</c> of <typeparamref name="T"/> on entity <paramref name="id"/>: the kept value back, stamped and
    /// indexed. False when it is not disabled. Inside the structural gate.
    /// </summary>
    internal bool EnableRow<T>(ref EntityMeta meta, int id, int version) where T : struct, IComponent
    {
        ushort bit = ComponentType<T>.Bit;
        if (!EnableBit(ref meta, bit, DisabledType<T>.Bit)) return false;
        meta.Archetype.Stamp<T>(meta.Slot, ChangeTick);
        Written(id, version, in Row<T>(ref meta, bit));
        return true;
    }

    /// <summary>
    /// Move entity <paramref name="id"/> along <paramref name="transition"/>: copy its shared components into a row of
    /// the target table and remove its old row. Components only the target has are left for the caller to write.
    /// Inside the structural gate. Not inlined: callers whose usual path needs no move (a component given back to its
    /// row) keep a small frame instead of the copy loops' registers.
    /// </summary>
    [MethodImpl(MethodImplOptions.NoInlining)]
    private void MoveTo(ref EntityMeta meta, int id, Transition transition)
    {
        var target = transition.Target;
        if (ReferenceEquals(target, transition.Source)) return;

        int slot = target.Add(id, meta.Version);
        int oldSlot = meta.Slot;
        meta.Archetype = target; // before the copy: meta is dead in its loop, which keeps the loop's registers free
        meta.Slot = slot;
        transition.CopyRow(oldSlot, slot);
        RemoveRow(transition.Source, oldSlot); // may move another entity into oldSlot (outside passes)
        StorageVersion++;
    }

    /// <summary>
    /// Whether <paramref name="to"/> (the entity's archetype, read outside the gate) still has a column the job writes.
    /// When the job removed every component it writes (or destroyed the entity), there is nothing to carry over and
    /// the gate is skipped. Reading outside the gate is safe here: component values have one owner thread (the one
    /// running the pass), so no other thread changes this entity's archetype meanwhile; the copy re-reads under the gate.
    /// </summary>
    private static bool KeepsAnyWritten(Archetype to, int writes, ReadOnlySpan<ushort> bits)
    {
        if (to == null) return false;
        for (int k = 0; k < bits.Length; k++)
            if ((writes >> k & 1) != 0 && to.ColumnIndex(bits[k]) >= 0)
                return true;
        return false;
    }

    /// <summary>
    /// After a pass's job changed the archetype of the entity it was visiting (row <paramref name="slot"/> of
    /// <paramref name="from"/> is a tombstone now): copy the components the job writes through its refs
    /// (<paramref name="writes"/>, bit k for <paramref name="bits"/>[k]) from the old row, where those writes landed,
    /// to the entity's new row. Nothing to do when the entity was destroyed. Cold path.
    /// </summary>
    [MethodImpl(MethodImplOptions.NoInlining)]
    internal void CarryOver(Archetype from, int slot, int id, int writes, ReadOnlySpan<ushort> bits)
    {
        if (writes == 0 || !KeepsAnyWritten(MetaRef(id).Archetype, writes, bits)) return;
        using (Structural())
        {
            ref var meta = ref MetaRef(id);
            var to = meta.Archetype;
            if (to == null || meta.Version != from.Slots[slot].Version) return; // destroyed (the id may be reused already)
            for (int k = 0; k < bits.Length; k++)
            {
                if ((writes >> k & 1) == 0) continue;
                int target = to.ColumnIndex(bits[k]);
                if (target < 0) continue; // removed by the job
                int source = from.ColumnIndex(bits[k]);
                Archetype.CopyElement(from.Info(source), from.Columns[source], slot, to.Columns[target], meta.Slot);
            }
        }
    }
}
